//#region src/server/multi-stage.ts
/** Whether a response-stage cache must reject a field it did not key itself by. */
function hasUnsupportedResponseStageVary(headers, keyedRequestHeaders = []) {
	const keyedFields = new Set([...keyedRequestHeaders].map((name) => name.trim().toLowerCase()).filter(Boolean));
	return (headers.get("Vary") ?? "").split(",").map((name) => name.trim().toLowerCase()).filter(Boolean).some((name) => name === "*" || !keyedFields.has(name));
}
//#endregion
export { hasUnsupportedResponseStageVary };
